css:
.sl-course-bento.sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-course-bento .sl-text-primary { color: var(--smartlearn-primary); }
.sl-course-bento .sl-text-emphasis { color: var(--smartlearn-text); }
.sl-course-bento .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-course-bento .sl-bg-card { background-color: var(--smartlearn-card-bg); border: 1px solid var(--smartlearn-card-border); }
.sl-course-bento .sl-hero-card { background-color: #111827; border: 0; }
.sl-course-bento .sl-border { border-color: var(--smartlearn-card-border); }
.sl-course-bento .sl-card-radius { border-radius: var(--smartlearn-radius, 1rem); }
.sl-course-bento h2, .sl-course-bento h3 { font-family: var(--smartlearn-heading-font, inherit); }
.sl-course-bento .sl-badge-btn {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    padding: 0.45em 0.85em;
}
.sl-course-bento .sl-hero-scrim { background: linear-gradient(to top, rgba(0, 0, 0, 0.9) 0%, rgba(0, 0, 0, 0.2) 80%); }
.sl-course-bento .sl-hero-sub { color: rgba(255, 255, 255, 0.92); }
.sl-course-bento .sl-hero-meta { color: rgba(255, 255, 255, 0.88); }
.sl-course-bento .sl-media-fallback { background-color: var(--smartlearn-card-bg); }
.sl-course-bento .sl-focus-ring:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 3px;
}
.sl-course-bento .sl-hover-zoom { transition: transform 0.6s ease; }
@media (hover: hover) and (prefers-reduced-motion: no-preference) {
    .sl-course-bento .sl-hover-card { transition: transform 0.3s ease, box-shadow 0.3s ease; }
    .sl-course-bento .sl-hover-card:hover { transform: translateY(-5px); box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.12); }
    .sl-course-bento .sl-hover-card:hover .sl-hover-zoom { transform: scale(1.05); }
}
@media (prefers-reduced-motion: reduce) {
    .sl-course-bento .sl-hover-zoom, .sl-course-bento .sl-hover-card { transition: none; }
}
@media (min-width: 992px) {
    .sl-course-bento { padding-top: 6rem !important; padding-bottom: 6rem !important; }
}
[dir="rtl"] .sl-course-bento .fa-arrow-right { transform: scaleX(-1); }
